from threading import Lock

class Reservations:
    def __init__(self):
        self.lock = Lock()
        self.claimed = set()

    def claim(self, item_id):
        with self.lock:
            if item_id in self.claimed:
                return False
            self.claimed.add(item_id)
            return True

